const PAGE="<!doctype html>\n<html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover,user-scalable=no\"><meta name=\"theme-color\" content=\"#7ebdee\"><title>POT BREAKER RE : CBZP v1.0.0</title>\n<style>\n:root{font-family:system-ui,'Malgun Gothic',sans-serif;--ink:#233558;--blue:#425f9d;--cream:#fff7e8;--orange:#ffba68}*{box-sizing:border-box}body{margin:0;min-height:100dvh;background:linear-gradient(145deg,#72bafa,#c8edff 65%,#fff5e8);color:var(--ink);overflow:hidden}button{font:inherit;border:0;cursor:pointer;touch-action:manipulation}button:focus-visible{outline:3px solid #ffa644;outline-offset:3px}.app{width:100%;height:100dvh;display:grid;place-items:center}.screen{width:min(100vw,calc(100dvh * 1.77778));height:min(100dvh,calc(100vw / 1.77778));position:relative;overflow:hidden;background:#edf9ff;border:1px solid #7795c0;box-shadow:0 18px 60px #40517e55}.cloud{position:absolute;width:180px;height:60px;border-radius:50%;background:#ffffffac;filter:blur(1px)}.cloud:before{content:\"\";position:absolute;background:inherit;border-radius:50%;width:90px;height:85px;left:30px;top:-40px}.cloud.one{top:8%;left:3%}.cloud.two{top:30%;right:5%;transform:scale(.7)}.panel{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:center;background:linear-gradient(145deg,#c1e6fcf5,#fff8ecf7)}.hidden{display:none!important}.card{max-height:94%;overflow:auto;width:min(94%,750px);background:#ffffffed;border:4px solid #465c90;border-radius:27px;box-shadow:0 11px 0 #52659545;padding:clamp(14px,2vw,28px);text-align:center}.logo{margin:0;font-weight:1000;font-size:clamp(28px,5.5vw,75px);letter-spacing:-.065em;line-height:1.03;color:#354c83;text-shadow:3px 3px #ffdf98,-2px -2px white}.logo span{color:#f28a4f}.tag{display:inline-block;margin:12px auto;padding:7px 20px;border-radius:99px;background:#fff0cd;font-weight:900;font-size:clamp(11px,1.2vw,16px)}.caption{font-size:clamp(13px,1.5vw,19px);line-height:1.6;font-weight:700}.mascots{font-size:clamp(43px,8vw,88px);margin:10px 0}.cta{margin:9px;background:#36538b;color:#fff;border:3px solid #fff;padding:11px 28px;border-radius:99px;font-size:clamp(12px,1.4vw,18px);font-weight:900;box-shadow:0 5px 0 #233558}.cta:active{transform:translateY(3px);box-shadow:none}.ghost{background:white;color:#36538b;border:2px solid #b3bcd2}.mini{font-size:clamp(10px,1.05vw,14px);color:#56647c}.comics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.comic{border:3px solid #7795b5;border-radius:12px;background:#f0f7ff;min-width:0;overflow:hidden}.comic .number{display:flex;align-items:center;justify-content:center;gap:8px;background:#d7eaff;padding:7px 4px;font-weight:900;font-size:clamp(9px,1vw,15px)}.comic b{color:#fff;background:#d4535e;padding:3px 7px;border-radius:50%}.art{height:clamp(66px,13vw,162px);display:flex;justify-content:center;align-items:center;gap:2px;font-size:clamp(28px,4.5vw,68px);background:linear-gradient(145deg,#a3caf1,#f6f4df)}.comic small{display:block;padding:7px 4px;min-height:43px;line-height:1.35;font-weight:700;font-size:clamp(9px,1vw,13px)}#gamePanel{background:#dde9ed;position:absolute;inset:0}.toolbar{position:absolute;z-index:3;top:7px;left:8px;right:8px;display:flex;justify-content:space-between;pointer-events:none;gap:8px}.hud{border:2px solid #394e7f;border-radius:12px;background:#fffdf0e8;padding:5px 9px;font-weight:900;font-size:clamp(10px,1.2vw,16px);white-space:nowrap}.hud.cat{border-color:#6e97d7}.hud.boss{border-color:#c38369}.info{font-size:clamp(9px,1vw,12px);font-weight:800;text-align:center;max-width:38%;align-self:flex-start;white-space:normal}#board{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}#controls{position:absolute;inset:0;z-index:2;pointer-events:none}.pad{position:absolute;bottom:clamp(8px,2.2vw,22px);left:clamp(11px,3vw,30px);display:grid;grid-template-columns:repeat(3,clamp(36px,6.5vw,66px));grid-template-rows:repeat(3,clamp(30px,4.7vw,51px));align-items:center;justify-items:center;pointer-events:auto}.pad button{width:96%;height:96%;background:#ffffffc9;border:2px solid #6886b7;border-radius:10px;color:#375486;font-weight:900;user-select:none}.pad button.pressed{background:#ffe7b0}.pad .up{grid-column:2;grid-row:1}.pad .left{grid-column:1;grid-row:2}.pad .down{grid-column:2;grid-row:3}.pad .right{grid-column:3;grid-row:2}.pad .center{grid-column:2;grid-row:2;opacity:.4;pointer-events:none}.actions{position:absolute;bottom:clamp(13px,3vw,34px);right:clamp(13px,3vw,34px);display:flex;align-items:end;gap:10px;pointer-events:auto}.action{height:clamp(53px,9vw,99px);width:clamp(53px,9vw,99px);border:4px solid white;border-radius:50%;background:#f8c680;color:#2f416d;font-weight:1000;font-size:clamp(11px,1.6vw,17px);box-shadow:0 5px 0 #43598359}.action.jump{background:#c4dbff}.action:disabled{opacity:.45;filter:grayscale(1)}.help{position:absolute;bottom:4px;left:50%;transform:translateX(-50%);z-index:2;color:#263c57;font-size:clamp(9px,.9vw,12px);font-weight:800;background:#fff6;padding:2px 8px;border-radius:8px;pointer-events:none}#notice{position:absolute;top:13%;left:50%;transform:translateX(-50%);background:#fffbe8e8;padding:6px 15px;border-radius:20px;border:2px solid #8796ba;font-weight:900;font-size:clamp(10px,1.25vw,15px);z-index:2;pointer-events:none;white-space:nowrap}#bell{position:absolute;top:21%;left:50%;transform:translateX(-50%);font-size:clamp(17px,2.5vw,30px);font-weight:1000;color:#ad6023;text-shadow:1px 2px #fff;z-index:2;pointer-events:none}#loader{position:absolute;inset:0;z-index:7;display:grid;place-items:center;background:#eff8ff}.spinner{width:40px;height:40px;border:5px solid #d7e9ff;border-top-color:#3c5a91;border-radius:50%;animation:spin 1s linear infinite;margin:auto auto 12px}@keyframes spin{to{transform:rotate(360deg)}}#end .card{width:min(92%,550px)}#endArt{font-size:clamp(55px,9vw,115px)}.scene{margin:10px;background:linear-gradient(#e0eeff,#fff2db);border:4px solid #4b648f;border-radius:16px;padding:12px;font-weight:900}small.warn{display:block;color:#945235;margin:6px auto}@media (max-aspect-ratio:1/1){.app:before{content:'📱 스마트폰은 가로로 돌려 플레이하세요';font-weight:900;position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:#e5f4ff;text-align:center;padding:24px}}\n</style></head>\n<body><div class=\"app\"><main class=\"screen\"><div class=\"cloud one\"></div><div class=\"cloud two\"></div>\n<section id=\"title\" class=\"panel\"><div class=\"card\"><div class=\"mini\">CLOUD BEAR ZOO PARK PRESENTS</div><h1 class=\"logo\">🪴 POT BREAKER<br><span>RE : CBZP</span></h1><div class=\"tag\">인턴 기묘의 살아남기 프로젝트 · v1.0.0</div><div class=\"mascots\">🐈‍⬛ &nbsp; 🐊 &nbsp; 🐦‍⬛</div><p class=\"caption\">수상한 사무실. 날아오는 화분.<br>인턴 기묘의 목표는 단 하나 — 크다 부장의 뚝배기!</p><button class=\"cta\" id=\"openIntro\">게임 시작</button><p class=\"mini\">스마트폰 가로모드 · 터치 / PC 키보드 조작 · 싱글플레이</p></div></section>\n<section id=\"intro\" class=\"panel hidden\"><div class=\"card\" style=\"width:96%;max-width:1100px\"><div class=\"tag\">CBZP 입사 첫날 | 오프닝 4컷</div><div class=\"comics\"><div class=\"comic\"><div class=\"number\"><b>1</b>첫 출근</div><div class=\"art\">🏢 🐈</div><small>\"잘 부탁드립니다…!\"<br>인턴 기묘, CBZP 입사.</small></div><div class=\"comic\"><div class=\"number\"><b>2</b>이상한 사무실</div><div class=\"art\">🐦‍⬛ 🐊 🐈</div><small>\"여기… 뭔가 이상한데?\"</small></div><div class=\"comic\"><div class=\"number\"><b>3</b>휙!</div><div class=\"art\">🪴💨 🐈</div><small>어디선가 날아온 화분! 고양이답게 피하는 기묘.</small></div><div class=\"comic\"><div class=\"number\"><b>4</b>추격전</div><div class=\"art\">🐊🪴 ➜ 🐈</div><small>덩치 큰 누군가가 따라온다. 살아남을 수 있을까?</small></div></div><button class=\"cta\" id=\"begin\">사무실로 들어가기</button><div class=\"mini\">이동: 방향키/WASD 또는 화면 방향 버튼 · 벽 넘기: Shift · 화분 던지기: Space</div></div></section>\n<section id=\"gamePanel\" class=\"hidden\"><canvas id=\"board\" aria-label=\"CBZP 사무실 미로 게임\"></canvas><div class=\"toolbar\"><div class=\"hud cat\">🐈 기묘 <span id=\"catHud\">🪴 1 · 벽넘기 1/3</span></div><div class=\"hud info\">POT BREAKER RE · v1.0.0</div><div class=\"hud boss\">🐊 크다 부장 <span id=\"bossHud\">🪴 2</span></div></div><div id=\"notice\"></div><div id=\"bell\" class=\"hidden\">딸랑딸랑</div><div id=\"controls\"><div class=\"pad\" role=\"group\" aria-label=\"이동\"><button class=\"up\" data-dir=\"up\">▲</button><button class=\"left\" data-dir=\"left\">◀</button><button class=\"center\" disabled>✦</button><button class=\"right\" data-dir=\"right\">▶</button><button class=\"down\" data-dir=\"down\">▼</button></div><div class=\"actions\"><button class=\"action jump\" id=\"jump\" aria-label=\"벽 넘기\">벽 넘기<br><span id=\"stackLabel\">1/3</span></button><button class=\"action\" id=\"fire\" aria-label=\"화분 던지기\">🪴<br>던지기</button></div></div><div class=\"help\">크다는 좌우 150° 시야 · 파티션은 시야를 가리지 않음 · 방울은 방향 표시 없음</div></section>\n<section id=\"end\" class=\"panel hidden\"><div class=\"card\"><div class=\"tag\" id=\"endTag\">승부 완료</div><div class=\"scene\"><div id=\"endArt\">🐈🪴🐊</div><p class=\"caption\" id=\"endText\"></p></div><button class=\"cta\" id=\"again\">다시 도전</button><button class=\"cta ghost\" id=\"home\">메인으로</button></div></section>\n<section id=\"loader\" class=\"hidden\"><div class=\"card\"><div class=\"spinner\"></div><strong>Python 게임 엔진을 불러오는 중…</strong><p class=\"mini\">첫 실행에는 Python WebAssembly 모듈을 다운로드합니다.</p><p class=\"mini\" id=\"loadStatus\"></p></div></section>\n</main></div>\n<script type=\"text/plain\" id=\"python-source\">\nimport random, math, json\n\nWIDTH, HEIGHT = 19, 11\n\n\ndef distance(a, b):\n    return math.hypot(a[0] - b[0], a[1] - b[1])\n\n\nclass PotBreaker:\n    \"\"\"Single-player office maze rules; deterministic JSON state for Canvas UI.\"\"\"\n\n    def __init__(self, seed=None):\n        self.rng = random.Random(seed)\n        self.reset()\n\n    def reset(self):\n        self.phase = 'playing'\n        self.clock = 0.0\n        self.player = list(self.rng.choice([(1, 1), (1, HEIGHT - 2), (WIDTH - 2, 1), (WIDTH - 2, HEIGHT - 2)]))\n        self.boss = [WIDTH // 2, HEIGHT // 2]\n        self.face = [1, 0]\n        self.boss_face = [1, 0]\n        self.walls = set()\n        safe = {tuple(self.player), tuple(self.boss)}\n        for y in range(1, HEIGHT-1):\n            for x in range(1, WIDTH-1):\n                if (x, y) not in safe and abs(x - self.player[0]) + abs(y - self.player[1]) > 2 and abs(x - self.boss[0]) + abs(y - self.boss[1]) > 2 and self.rng.random() < 0.23:\n                    self.walls.add((x, y))\n        # Carve openings if a random partition layout blocks every route.\n        while self.walls and not self._is_connected(self.player, self.boss):\n            self.walls.remove(self.rng.choice(tuple(self.walls)))\n        self.ammo = 1\n        self.boss_ammo = 2\n        self.jump_stacks = 1.0\n        self.boss_jump_cd = 0.0\n        self.throw_cd = 0.0\n        self.boss_throw_cd = 1.5\n        self.player_move_cd = 0.0\n        self.boss_move_cd = 0.4\n        self.alert = 0.0\n        self.last_seen = None\n        self.bell = 0.0\n        self.notice = '크다 부장의 시야를 피해 이동하세요.'\n        self.notice_time = 2.2\n        self.projectiles = []\n        self.pots = []\n        self.roam = None\n        for _ in range(3):\n            self._add_pot()\n        return self.state()\n\n    def _free(self, x, y):\n        return 0 <= x < WIDTH and 0 <= y < HEIGHT and (x, y) not in self.walls\n\n    def _is_connected(self, start, goal):\n        q, seen = [tuple(start)], {tuple(start)}\n        for x, y in q:\n            if (x, y) == tuple(goal):\n                return True\n            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n                nx, ny = x + dx, y + dy\n                if self._free(nx, ny) and (nx, ny) not in seen:\n                    seen.add((nx, ny))\n                    q.append((nx, ny))\n        return False\n\n    def _add_pot(self):\n        choices = [(x, y) for x in range(WIDTH) for y in range(HEIGHT)\n                   if self._free(x, y) and [x, y] not in (self.player, self.boss) and [x, y] not in self.pots]\n        if choices:\n            self.pots.append(list(self.rng.choice(choices)))\n\n    def _path_step(self, start, goal):\n        start, goal = tuple(start), tuple(goal)\n        if start == goal:\n            return start\n        q = [start]\n        came = {start: None}\n        for p in q:\n            if p == goal:\n                break\n            for dx, dy in self.rng.sample([(0,1),(1,0),(0,-1),(-1,0)], 4):\n                n = (p[0]+dx, p[1]+dy)\n                if self._free(*n) and n not in came:\n                    came[n] = p\n                    q.append(n)\n        if goal not in came:\n            return start\n        p = goal\n        while came[p] not in (None, start):\n            p = came[p]\n        return p\n\n    def _sees_player(self):\n        # Partition walls do NOT obstruct vision; configurable distance is in grid cells.\n        if distance(self.player, self.boss) > 3.4:\n            return False\n        dx, dy = self.player[0] - self.boss[0], self.player[1] - self.boss[1]\n        theta = abs(math.degrees(math.atan2(self.boss_face[0]*dy-self.boss_face[1]*dx,\n                                             self.boss_face[0]*dx+self.boss_face[1]*dy)))\n        return 5 <= theta <= 155\n\n    def _pickups(self):\n        for who, cap, attr in ((self.player, 1, 'ammo'), (self.boss, 2, 'boss_ammo')):\n            if getattr(self, attr) >= cap:\n                continue\n            for pot in list(self.pots):\n                if distance(who, pot) < 0.65:\n                    setattr(self, attr, getattr(self, attr) + 1)\n                    self.pots.remove(pot)\n                    self._add_pot()\n                    break\n\n    def _fire(self, who, vec, boss=False):\n        ammo_field = 'boss_ammo' if boss else 'ammo'\n        if getattr(self, ammo_field) < 1:\n            return\n        length = math.hypot(*vec)\n        if length < 0.001:\n            vec, length = [1, 0], 1\n        setattr(self, ammo_field, getattr(self, ammo_field) - 1)\n        self.projectiles.append({'x':float(who[0]),'y':float(who[1]),\n                                 'dx':vec[0]/length,'dy':vec[1]/length,\n                                 'range':7.3 if boss else 4.2,'boss':boss})\n\n    def _jump_player(self, dx, dy):\n        if self.jump_stacks < 1 or not (dx or dy):\n            return False\n        x, y = self.player\n        if (x+dx,y+dy) not in self.walls or not self._free(x+2*dx,y+2*dy):\n            return False\n        self.player = [x+2*dx,y+2*dy]\n        self.jump_stacks -= 1\n        return True\n\n    def _move_boss(self):\n        visible = self._sees_player()\n        if visible:\n            self.last_seen = list(self.player)\n            self.alert = 2.8\n        target = self.last_seen if self.alert > 0 and self.last_seen else None\n        if not target:\n            if self.roam is None or self.boss == self.roam or self.rng.random() < .10:\n                self.roam = [self.rng.randrange(1,WIDTH-1), self.rng.randrange(1,HEIGHT-1)]\n            target = self.roam\n        dx = 0 if target[0] == self.boss[0] else (1 if target[0] > self.boss[0] else -1)\n        dy = 0 if target[1] == self.boss[1] else (1 if target[1] > self.boss[1] else -1)\n        primary = (dx,0) if abs(target[0]-self.boss[0]) >= abs(target[1]-self.boss[1]) else (0,dy)\n        if primary == (0,0):\n            primary = (dx,dy)\n        if visible and self.boss_jump_cd <= 0 and self.boss_ammo > 0:\n            for d in ([primary,(0,dy),(dx,0)]):\n                if d == (0,0):\n                    continue\n                tx, ty = self.boss\n                count = 0\n                while (tx+d[0],ty+d[1]) in self.walls and count < 3:\n                    tx += d[0]\n                    ty += d[1]\n                    count += 1\n                if count and self._free(tx+d[0],ty+d[1]):\n                    self.boss = [tx+d[0], ty+d[1]]\n                    self.boss_face = list(d)\n                    self.boss_jump_cd = 15.0\n                    self.notice, self.notice_time = '쾅! 크다 부장이 파티션을 뚫었습니다!', 0.9\n                    return\n        nxt = self._path_step(self.boss, target)\n        if nxt != tuple(self.boss):\n            self.boss_face = [nxt[0]-self.boss[0],nxt[1]-self.boss[1]]\n            self.boss = list(nxt)\n        elif not visible:\n            self.roam = None\n\n    def _advance_projectiles(self, dt):\n        for p in list(self.projectiles):\n            p['x'] += p['dx'] * dt * (7.1 if p['boss'] else 9.6)\n            p['y'] += p['dy'] * dt * (7.1 if p['boss'] else 9.6)\n            p['range'] -= dt * (7.1 if p['boss'] else 9.6)\n            if p['range'] <= 0 or not (0 <= p['x'] < WIDTH and 0 <= p['y'] < HEIGHT):\n                self.projectiles.remove(p)\n                continue\n            if not p['boss'] and (round(p['x']),round(p['y'])) in self.walls:\n                self.projectiles.remove(p)\n                continue\n            for other in list(self.projectiles):\n                if other is p or other['boss'] == p['boss']:\n                    continue\n                if math.hypot(p['x']-other['x'],p['y']-other['y']) < .5:\n                    small = p if not p['boss'] else other\n                    if small in self.projectiles:\n                        self.projectiles.remove(small)\n                    break\n            if p not in self.projectiles:\n                continue\n            target = self.player if p['boss'] else self.boss\n            if distance((p['x'],p['y']),target) < .56:\n                self.phase = 'lose' if p['boss'] else 'win'\n                self.projectiles.clear()\n                break\n\n    def step(self, dt, mx=0, my=0, jump=False, fire=False, aimx=0, aimy=0):\n        if self.phase != 'playing':\n            return self.state()\n        dt = min(.085,max(0.01,float(dt)))\n        self.clock += dt\n        self.jump_stacks = min(3.,self.jump_stacks+dt/5.)\n        self.boss_jump_cd = max(0.,self.boss_jump_cd-dt)\n        self.throw_cd = max(0.,self.throw_cd-dt)\n        self.boss_throw_cd = max(0.,self.boss_throw_cd-dt)\n        self.player_move_cd -= dt\n        self.boss_move_cd -= dt\n        self.notice_time = max(0.,self.notice_time-dt)\n        self.bell = max(0.,self.bell-dt)\n        self.alert = max(0.,self.alert-dt)\n        dx, dy = int(mx), int(my)\n        if dx and dy:\n            dy = 0\n        if dx or dy:\n            self.face = [dx,dy]\n        if jump and (dx or dy):\n            if self._jump_player(dx,dy):\n                self.player_move_cd = .10\n        if self.player_move_cd <= 0 and (dx or dy):\n            tx,ty = self.player[0]+dx,self.player[1]+dy\n            if self._free(tx,ty):\n                self.player = [tx,ty]\n            self.player_move_cd = .115\n        if fire and self.throw_cd <= 0 and self.ammo:\n            self._fire(self.player,[float(aimx) if aimx or aimy else self.face[0],\n                                    float(aimy) if aimx or aimy else self.face[1]])\n            self.throw_cd = .40\n        if self.boss_move_cd <= 0:\n            self._move_boss()\n            self.boss_move_cd = .32\n        if self.boss_throw_cd <= 0 and self.boss_ammo and distance(self.player,self.boss) < 7.4 and self._sees_player():\n            self._fire(self.boss,[self.player[0]-self.boss[0],self.player[1]-self.boss[1]],True)\n            self.boss_throw_cd = 2.8\n        if (dx or dy) and distance(self.player,self.boss) <= 5:\n            self.bell = .7\n        self._advance_projectiles(dt)\n        self._pickups()\n        return self.state()\n\n    def state(self):\n        return json.dumps({'phase':self.phase,'player':self.player,'boss':self.boss,\n            'face':self.face,'boss_face':self.boss_face,'walls':list(self.walls),'pots':self.pots,\n            'ammo':self.ammo,'boss_ammo':self.boss_ammo,'stacks':int(self.jump_stacks),\n            'jump_progress':round(self.jump_stacks%1,2),'boss_cd':round(self.boss_jump_cd,1),\n            'bell':self.bell>0,'notice':self.notice if self.notice_time else '',\n            'projectiles':self.projectiles,'vision_radius':3.4},ensure_ascii=False)\n\nif __name__ == '__main__' and not globals().get('IN_BROWSER', False):\n    game=PotBreaker(9)\n    for i in range(2000):\n        s=json.loads(game.step(.04,1 if i%6 < 3 else -1, 0, i%30==0, i%18==0,1,0))\n        assert len(s['pots'])==3 and 0<=s['stacks']<=3\n        if s['phase']!='playing': game.reset()\n    print('OK: 2000 ticks')\n</script>\n<script src=\"https://cdn.jsdelivr.net/pyodide/v0.27.7/full/pyodide.js\"></script>\n<script>\n(()=>{'use strict';const $=id=>document.getElementById(id);const canvas=$('board'),ctx=canvas.getContext('2d');let game=null,pyodide=null,frame=0,last=0,loading=false,active=false,aim=null,keys=new Set(),touchDir=null,requestJump=false,requestFire=false;\nconst W=19,H=11,show=id=>{for(const pane of ['title','intro','gamePanel','end'])$(pane).classList.toggle('hidden',pane!==id)};\nconst dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};\n$('openIntro').onclick=()=>show('intro');$('home').onclick=()=>{active=false;cancelAnimationFrame(frame);show('title')};$('begin').onclick=()=>launch();$('again').onclick=()=>launch();\nfor(const b of document.querySelectorAll('[data-dir]')){const name=b.dataset.dir;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touchDir=name;b.classList.add('pressed')};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>{if(touchDir===name)touchDir=null;b.classList.remove('pressed')})}\n$('jump').addEventListener('pointerdown',e=>{e.preventDefault();requestJump=true});$('fire').addEventListener('pointerdown',e=>{e.preventDefault();requestFire=true});window.addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys.add(e.code);if(['ShiftLeft','ShiftRight'].includes(e.code))requestJump=true;if(e.code==='Space')requestFire=true});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();touchDir=null});\ncanvas.addEventListener('pointerdown',e=>{if(!game)return;const r=canvas.getBoundingClientRect();aim=[(e.clientX-r.left)/r.width*W,(e.clientY-r.top)/r.height*H];requestFire=true});canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){const r=canvas.getBoundingClientRect();aim=[(e.clientX-r.left)/r.width*W,(e.clientY-r.top)/r.height*H]}});\nasync function load(){if(pyodide)return;if(loading)return;loading=true;$('loader').classList.remove('hidden');try{if(!window.loadPyodide)throw new Error('Python 런타임 로드 실패. 인터넷 연결을 확인하세요.');pyodide=await loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v0.27.7/full/'});const py=$('python-source').textContent;pyodide.runPython('IN_BROWSER=True\\n'+py+'\\ngame=PotBreaker()');game=pyodide.globals.get('game');}finally{loading=false;$('loader').classList.add('hidden')}}\nasync function launch(){try{await load();if(active){cancelAnimationFrame(frame)}let raw=game.reset();let state=JSON.parse(raw);active=true;show('gamePanel');last=performance.now();frame=requestAnimationFrame(loop);draw(state)}catch(e){$('loadStatus').textContent=String(e);$('loader').classList.remove('hidden');setTimeout(()=>{ $('loader').classList.add('hidden');alert(String(e))},250)}}\nfunction getMove(){for(const [key,d] of [['ArrowUp','up'],['KeyW','up'],['ArrowDown','down'],['KeyS','down'],['ArrowLeft','left'],['KeyA','left'],['ArrowRight','right'],['KeyD','right']])if(keys.has(key))return dirs[d];return dirs[touchDir]||[0,0]}\nlet acc=0,current=null;function loop(now){if(!active)return;let dt=Math.min(.12,(now-last)/1000||.02);last=now;acc+=dt;let n=0;while(acc>=.04&&n++<3){const [mx,my]=getMove();let ax=0,ay=0;if(aim&&current){ax=aim[0]-current.player[0];ay=aim[1]-current.player[1]}let raw=game.step(.04,mx,my,requestJump,requestFire,ax,ay);requestJump=false;requestFire=false;current=JSON.parse(raw);acc-=.04;if(current.phase!=='playing')break}if(current)draw(current);if(current&&current.phase!=='playing'){active=false;setTimeout(()=>ending(current.phase),700);return}frame=requestAnimationFrame(loop)}\nfunction ending(phase){show('end');if(phase==='win'){$('endTag').textContent='기묘 승리!';$('endArt').textContent='🐈🪴💥🐊';$('endText').textContent='쾅! 기묘의 화분이 크다 부장의 뚝배기를 깨버렸다!'}else{$('endTag').textContent='크다 부장 승리';$('endArt').textContent='🐊 👑 🪴🐈';$('endText').textContent='기묘는 화분에 머리만 내놓은 채 심어졌다…'}}\nfunction roundedRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.05;ctx.stroke()}}\nfunction cat(x,y,face){ctx.save();ctx.translate(x+.5,y+.5);ctx.fillStyle='#817b78';ctx.strokeStyle='#45465b';ctx.lineWidth=.06;ctx.beginPath();ctx.ellipse(0,.08,.31,.36,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#c1a9a1';for(const xx of [-.2,.2]){ctx.beginPath();ctx.moveTo(xx,-.18);ctx.lineTo(xx*1.65,-.48);ctx.lineTo(xx*.2,-.42);ctx.fill()}ctx.beginPath();ctx.ellipse(0,-.13,.35,.30,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#f8f0e5';ctx.fillRect(-.28,.12,.56,.26);ctx.fillStyle='#80756c';ctx.beginPath();ctx.arc(.22,.37,.16,0,Math.PI);ctx.stroke();ctx.restore()}\nfunction boss(x,y,f){ctx.save();ctx.translate(x+.5,y+.5);ctx.fillStyle='#283a49';ctx.beginPath();ctx.ellipse(0,.13,.43,.36,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#93b76b';ctx.beginPath();ctx.ellipse(0,-.16,.39,.38,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#364e43';ctx.lineWidth=.06;ctx.stroke();ctx.fillStyle='#e99c55';for(let i=-2;i<=2;i++){ctx.beginPath();ctx.arc(-.28+i*.13,-.43,.08,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#fff1cf';ctx.fillRect(-.36,.07,.72,.05);ctx.restore()}\nfunction plant(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#cc804e';ctx.beginPath();ctx.moveTo(-.22,-.02);ctx.lineTo(.22,-.02);ctx.lineTo(.16,.31);ctx.lineTo(-.15,.31);ctx.closePath();ctx.fill();ctx.fillStyle='#6e9e53';for(const [ox,oy] of [[0,-.25],[-.14,-.16],[.14,-.16]]){ctx.beginPath();ctx.ellipse(ox,oy,.12,.18,ox,0,Math.PI*2);ctx.fill()}ctx.restore()}\nfunction draw(s){current=s;const dpr=Math.min(2,window.devicePixelRatio||1),b=canvas.getBoundingClientRect(),wid=Math.round(b.width*dpr),hei=Math.round(b.height*dpr);if(canvas.width!==wid||canvas.height!==hei){canvas.width=wid;canvas.height=hei}ctx.setTransform(wid/W,0,0,hei/H,0,0);ctx.fillStyle='#f5eee3';ctx.fillRect(0,0,W,H);for(let y=0;y<H;y++)for(let x=0;x<W;x++){ctx.fillStyle=(x+y)%2===0?'#f6f0e8':'#eae7e1';ctx.fillRect(x,y,1,1);ctx.strokeStyle='#d6d5da';ctx.lineWidth=.016;ctx.strokeRect(x,y,1,1);if((x*5+y*11)%31===0){ctx.fillStyle='#b5c3c9';ctx.fillRect(x+.13,y+.11,.75,.17);ctx.fillStyle='#f9fcff';ctx.fillRect(x+.21,y+.32,.54,.30)}}for(const [x,y] of s.walls){roundedRect(x+.02,y+.07,.96,.84,.06,'#b6c4cf','#738ba9');ctx.fillStyle='#8c9fae';ctx.fillRect(x+.12,y+.15,.76,.10)}for(const [x,y] of s.pots)plant(x+.5,y+.45,.85);const cx=s.boss[0]+.5,cy=s.boss[1]+.5,ang=Math.atan2(s.boss_face[1],s.boss_face[0]);const vision=s.vision_radius;for(const side of [-1,1]){ctx.beginPath();ctx.moveTo(cx,cy);const a=ang+(side===-1?-155:5)*Math.PI/180,bb=ang+(side===-1?-5:155)*Math.PI/180;ctx.arc(cx,cy,vision,a,bb);ctx.closePath();ctx.fillStyle='#f06a6a32';ctx.fill()}boss(...s.boss,s.boss_face);cat(...s.player,s.face);for(const p of s.projectiles)plant(p.x+.5,p.y+.35,p.boss?.92:.63);$('catHud').textContent='🪴 '+s.ammo+' · 벽넘기 '+s.stacks+'/3';$('bossHud').textContent='🪴 '+s.boss_ammo+' · 벽 '+(s.boss_cd>0?s.boss_cd+'s':'준비');$('stackLabel').textContent=s.stacks+'/3';$('jump').disabled=s.stacks<1;$('fire').disabled=s.ammo<1;$('notice').textContent=s.notice;$('notice').style.display=s.notice?'':'none';$('bell').classList.toggle('hidden',!s.bell)}\n})();\n</script></body></html>";
export default {async fetch(request){const u=new URL(request.url);if(u.pathname==='/health')return new Response(JSON.stringify({ok:true,version:'1.0.0',engine:'Python/Pyodide'}),{headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});if(u.pathname!=='/'&&u.pathname!=='/index.html')return new Response('Not Found',{status:404});return new Response(PAGE,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'public, max-age=60','x-content-type-options':'nosniff'}})}};